local logs = {}
for p = 1, 2 do
  local r = tool('search_logs', { service = 'payments', level = 'ERROR', page = p })
  for _, item in ipairs(r.items) do
    logs[#logs + 1] = { ts = item.ts, message = item.message }
  end
end
local owner = tool('get_service_owners', { service = 'payments' })
return { logs = logs, owner = owner }
